import{z as i,x as A,o as n,c,q as l,j as r,D as E,d as a,s,S as d,b as o}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"Volcano 迭代器","description":"","frontmatter":{"title":"Volcano 迭代器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/volcano-iterator.md","filePath":"cs/volcano-iterator.md","lastUpdated":1791063341000}'),p={name:"cs/volcano-iterator.md"};function B(D,e,x,C,m,u){const t=A("Mermaid");return n(),c("div",null,[e[2]||(e[2]=l('<h1 id="volcano-迭代器" tabindex="-1">Volcano 迭代器 <a class="header-anchor" href="#volcano-迭代器" aria-label="Permalink to &quot;Volcano 迭代器&quot;">​</a></h1><div class="epigraph"><p>每个算子暴露 open / next / close；父亲拉儿子，一次一行。树是计划，时钟在 next 的调用栈上。</p><footer>—— 据 Graefe, Volcano—An Extensible and Parallel Query Evaluation System, TKDE 1994；Graefe 查询执行综述</footer></div><p>优化器在<a href="/cs/plan-regression">计划回归</a>封口。本课打开执行引擎：计划树已定，如何变成元组流。缺口是 Volcano（迭代器 / 拉模型）：统一接口让连接、选择、扫描可任意组装，并行用 exchange 插进同一接口。主干连接算法讲形状，不讲调用约定。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>物化模型：子算子跑完把整表放临时文件，父再读——简单，内存与延迟差。迭代器：父要一行就 <code>next()</code> 子，子再 <code>next()</code> 孙。流水线：选择可以在扫描吐行时立刻过滤，不必先落盘。缺口是<strong>控制流在算子里</strong>：阻塞算子（排序、哈希 build）在第一次 <code>next()</code> 时把输入吸干，之后才吐。</p><p><span class="marginnote">拉模型可翻译成「上游不主动，下游说了算」：数据只在父亲调儿子的 next 时才流动，像拧开水龙头才有水；推模型相反，上游产多少推多少。Volcano 选拉，是为了让过滤、连接这些算子能按需节流、随取随停。</span></p><p><code>open</code> 分配状态，<code>close</code> 释放扫描与文件。错误与取消走 <code>close</code>。本课不把每家执行器的向量批次当 Volcano 否定；向量化下一课是同一接口上的批量化。</p><p><span class="marginnote">Graefe Volcano，IEEE TKDE 1994。并行：exchange 算子也实现 next，下面接其他线程的队列。本课点名，并行课再写。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>扫描：<code>next</code> 返回下一槽化记录或空。选择：循环调用子 <code>next</code> 直到谓词真。NLJ：外层一行，内层 <code>open</code> 探测。哈希连接：build 在首次 next 阻塞完成，probe 流水。排序：阻塞。</p><p>资源：每个算子估内存；总内存超则算子内落盘（外部排序、Grace 哈希后课）。迭代器不自动解决内存，只规定谁拉谁。</p><p><span class="marginnote">数字实例：一行元组流经「扫描到过滤再到投影」要穿过三层 next，每层一次虚调用；十亿行的 OLAP 扫描就是几十亿次虚调用，CPU 时间相当可观——这正是向量化把「一次一行」改成「一次一批」要摊掉的那笔解释器税。</span></p>',12)),(n(),r(d,null,{default:E(()=>[s(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%20next%22%5D%20--%3E%20P%5B%22%E7%88%B6%E7%AE%97%E5%AD%90%22%5D%0A%20%20P%20--%3E%20C1%5B%22%E5%AD%90%20next%22%5D%0A%20%20C1%20--%3E%20C2%5B%22%E5%AD%99%20next%22%5D%0A%20%20C2%20--%3E%20SCAN%5B%22%E6%89%AB%E6%8F%8F%E6%A7%BD%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=o("h2",{id:"机制",tabindex:"-1"},[a("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=o("p",null,"解释器开销：每行多次虚调用，在 OLTP 宽行上可忽略，在 OLAP 窄扫描上占 CPU——向量化与编译执行要消灭的就是这条路径。NULL 与投影：迭代器携带的是槽或 RID+解引用；延迟物化后课决定何时读列。",-1)),e[5]||(e[5]=o("p",null,[a("取消查询："),o("code",null,"close"),a(" 沿树向下，阻塞在排序的算子也要能被中断。这是执行契约，不是优化器。")],-1)),(n(),r(d,null,{default:E(()=>[s(t,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20TREE%5B%22%E8%AE%A1%E5%88%92%E6%A0%91%22%5D%20--%3E%20PIPE%5B%22%E6%B5%81%E6%B0%B4%E7%AE%97%E5%AD%90%3A%20%E6%89%AB%E6%8F%8F%2C%20%E8%BF%87%E6%BB%A4%2C%20%E6%8A%95%E5%BD%B1%22%5D%0A%20%20TREE%20--%3E%20BLOCK%5B%22%E9%98%BB%E5%A1%9E%E7%AE%97%E5%AD%90%3A%20%E6%8E%92%E5%BA%8F%2C%20%E5%93%88%E5%B8%8C%20build%22%5D%0A%20%20PIPE%20--%3E%20DRIP%5B%22%E7%88%B6%E8%A6%81%E4%B8%80%E8%A1%8C%E5%90%90%E4%B8%80%E8%A1%8C%22%5D%0A%20%20BLOCK%20--%3E%20DRAIN%5B%22%E9%A6%96%E6%AC%A1%20next%20%E5%90%B8%E5%B9%B2%E8%BE%93%E5%85%A5%E5%90%8E%E6%89%8D%E8%83%BD%E5%90%90%22%5D%0A%20%20DRIP%20--%3E%20MEM%5B%22%E5%86%85%E5%AD%98%E5%8D%A0%E7%94%A8%E5%B0%8F%2C%20%E9%A6%96%E8%A1%8C%E6%9D%A5%E5%BE%97%E5%BF%AB%22%5D%0A%20%20DRAIN%20--%3E%20TMP%5B%22%E8%BE%93%E5%85%A5%E8%90%BD%E7%9B%98%2C%20%E5%BB%B6%E8%BF%9F%E5%8E%8B%E5%9C%A8%E9%A6%96%E8%A1%8C%22%5D%0A%20%20MEM%20--%3E%20CHOOSE%5B%22%E4%BC%98%E5%8C%96%E5%99%A8%E6%8D%AE%E6%AD%A4%E4%BC%B0%E5%86%85%E5%AD%98%E4%B8%8E%E6%8E%92%E5%B8%83%22%5D%0A%20%20TMP%20--%3E%20CHOOSE%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=l('<p><span class="marginnote">直觉类比：流水算子像流水线工人，来一件做一件；排序与哈希 build 像要集齐整批货才能开工的打包台——第一次被叫时先埋头把上游吸干（还可能落盘），之后才开箱吐结果，所以首行延迟高、内存峰值也压在它身上。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 SIMD 批次。也不把火山模型与流式系统的 operator graph 混名——后者常推模型。编译执行会把迭代器树打成循环，接口在源码层消失，语义仍是拉。</p><p>后课默认：计划树按 open/next/close 解释执行；阻塞点在排序与哈希 build。向量化把 next 的粒度从行换成批。</p><p>Volcano 是组装与并行插入的约定，不是一种连接算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>迭代器拉模型统一算子；阻塞算子在首次 next 物化输入。</li><li>每行调用开销是 OLAP 的 CPU 税。</li><li>向量化执行下一课：批处理摊掉解释器。</li><li>出处：Graefe, TKDE 1994；Graefe 执行综述。</li></ul>',7))])}const f=i(p,[["render",B]]);export{h as __pageData,f as default};
